887	// ghRunnerErr extracts an exec.ExitError's stderr into the returned
888	// error so the user sees a useful diagnostic when gh/git fail under a
889	// captured-stdout call.
890	func ghRunnerErr(err error) error {
891		var exitErr *exec.ExitError
892		if errors.As(err, &exitErr) && len(exitErr.Stderr) > 0 {
893			return fmt.Errorf("%w: %s", err, strings.TrimSpace(string(exitErr.Stderr)))
894		}
895		return err
896	}
