2761		cpID := group.checkpointID
2762		if len(cpID) > checkpointIDDisplayLength {
2763			cpID = cpID[:checkpointIDDisplayLength]
2764		}
2765	
2766		// Indicators (Task / temporary). Skip [temporary] when cpID already says so.
2767		var indicators []string
2768		if group.isTask {
2769			indicators = append(indicators, "[Task]")
2770		}
2771		if group.isTemporary && cpID != "temporary" {
2772			indicators = append(indicators, "[temporary]")
2773		}
2774	
2775		// Prompt cascade: SessionPrompt → latest commit message → dimmed placeholder.
2776		// Quote user prompts; commit subjects render bare.
2777		var promptText string
2778		var promptIsPlaceholder bool
2779		switch {
2780		case group.prompt != "":
2781			promptText = fmt.Sprintf("%q", strategy.TruncateDescription(group.prompt, maxPromptDisplayLength))
2782		case len(group.commits) > 0 && group.commits[0].message != "":
2783			promptText = strategy.TruncateDescription(group.commits[0].message, maxPromptDisplayLength)
2784		default:
2785			promptText = "(no prompt recorded)"
2786			promptIsPlaceholder = true
2787		}
2788		if promptIsPlaceholder {
2789			promptText = styles.render(styles.dim, promptText)
2790		}
2791	
2792		// Build suffix: "[Task]  [temporary]  <prompt>" with two-space separators.
2793		parts := append([]string{}, indicators...)
2794		parts = append(parts, promptText)
2795		suffix := strings.Join(parts, "  ")
2796	
2797		sb.WriteString(styles.listIdentityBullet(cpID, suffix))
2798	
2799		// List commits under this checkpoint.
2800		for _, commit := range group.commits {
2801			dateTimeStr := commit.date.Format("01-02 15:04")
2802			message := strategy.TruncateDescription(commit.message, maxMessageDisplayLength)
2803			fmt.Fprintf(sb, "  %s (%s) %s\n", dateTimeStr, commit.gitSHA, message)
