140	// filterActiveSessions returns sessions that have not been explicitly ended.
141	// A session is considered ended if Phase == PhaseEnded OR EndedAt is set.
142	// This matches the logic in status.go's writeActiveSessions for consistency:
143	// any session visible in `entire status` should also be visible in `sessions stop`.
144	func filterActiveSessions(states []*strategy.SessionState) []*strategy.SessionState {
145		var active []*strategy.SessionState
146		for _, s := range states {
147			if s == nil {
148				continue
149			}
150			if s.Phase != session.PhaseEnded && s.EndedAt == nil {
151				active = append(active, s)
152			}
153		}
154		return active
155	}
