267		// Line 2: > "prompt" (truncated)
268		if s.LastPrompt != "" {
269			prompt := stringutil.TruncateRunes(s.LastPrompt, 60, "...")
270			fmt.Fprintf(w, "%s \"%s\"\n", sty.render(sty.dim, ">"), prompt)
271		}
272	
273		// Line 3: status · started X ago · active X ago · tokens X.Xk
274		var stats []string
