281			stats = append(stats, "tokens "+formatTokenCount(t))
282		}
283		statsLine := strings.Join(stats, sty.render(sty.dim, " · "))
284		fmt.Fprintln(w, sty.render(sty.dim, statsLine))
285		fmt.Fprintln(w)
286	}
