	if err != nil {
		// Unborn HEAD (no commits yet) - return empty list instead of erroring
		if errors.Is(err, plumbing.ErrReferenceNotFound) {
			return []strategy.RewindPoint{}, nil
		}
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
